/* Platform administration and credits: local demonstration, never a security boundary. */
function initPlatform(){db.planLimits??=[{operations:2,users:null},{operations:null,users:null},{operations:null,users:null},{operations:null,users:null}];db.addonCredits??=0;db.addonRequests??=[];db.securityEvents??=[];db.platformStaff??=[];db.platformRole??='superadmin'}
initPlatform();let platformTab='overview';
const platformRoles={superadmin:'السوبر أدمن',subscriptions:'موظف الاشتراكات',security:'موظف مراقبة الدخول'};
function canPlatform(action){return db.platformRole==='superadmin'||(action==='security'&&db.platformRole==='security')||(action==='subscriptions'&&db.platformRole==='subscriptions')}
function currentLimits(){return db.planLimits[db.plan]||{operations:null,users:null}}
function operationBalance(){const limit=currentLimits().operations;return limit===null?null:Math.max(0,limit+db.addonCredits-db.ops.length)}
function assertOperationCredit(){if(currentLimits().operations===null)throw Error('لم يحدد السوبر أدمن حد عمليات هذه الباقة بعد');if(operationBalance()<1)throw Error('رصيد العمليات انتهى. اطلب شراء عملية إضافية')}
function requireOperationCredit(){try{assertOperationCredit();return true}catch(err){if(operationBalance()===0){go('addons');toast('انتهى رصيد إنشاء العمليات')}else toast(err.message);return false}}
function assertUserSlot(){const max=currentLimits().users;if(max===null)throw Error('حد المستخدمين لهذه الباقة لم يحدد بعد');if(db.users.length+1>=max)throw Error('وصلت إلى حد المستخدمين المسموح للباقة')}
function requireUserSlot(){try{assertUserSlot();return true}catch(err){toast(err.message);return false}}
function usageStrip(){let limit=currentLimits(),balance=operationBalance();return `<div class="usage-strip"><div>${icon('operations')} <b>${balance===null?'غير محدد':balance}</b><span>عمليات متاحة</span></div><div><b>${db.ops.length}</b><span>عمليات أُنشئت</span></div><div><b>${db.users.length+1} / ${limit.users??'—'}</b><span>مستخدمين، يشمل حساب الشركة</span></div><button onclick="go('addons')">شراء عمليات إضافية ${icon('plans')}</button></div>`}
const oldDashboard=dashboard,oldOperations=operations,oldTeam=team,oldSettings2=settings,oldPackageSummary=planSummary;
dashboard=function(){return usageStrip()+oldDashboard()};operations=function(){return usageStrip()+oldOperations()};team=function(){return usageStrip()+oldTeam()};
packageCards=function(){return `<div class="plans public-plans">${packages.map((p,i)=>{const limits=db.planLimits[i];return `<article class="pricing ${i===1?'selected':''}"><span class="badge">الباقة ${i+1}</span><h3>${p.name}</h3><div class="price">${p.price.toLocaleString('en')} <small>ر.س</small></div><p class="muted">لمدة ${p.days} يومًا</p><ul><li>${icon('operations')} ${limits.operations===null?'عدد العمليات يحدده السوبر أدمن':limits.operations+' عمليات جرد'}</li><li>${icon('team')} ${limits.users===null?'عدد المستخدمين يحدده السوبر أدمن':limits.users+' مستخدمين'}</li><li>${icon('scan')} جرد مفتوح أو بمرجع</li><li>${icon('plans')} عملية إضافية 50 ر.س · عمليتان 70 ر.س</li></ul><button class="${i===1?'primary':''}" onclick="choosePlan(${i})">اختيار الباقة ${icon('arrow')}</button></article>`}).join('')}</div>`};
planSummary=function(){let p=packages[chosenPlan],limits=db.planLimits[chosenPlan];return `<aside class="order-summary"><span class="badge">الباقة المختارة</span><h2>${p.name}</h2><div class="price">${p.price} <small>ر.س</small></div><p>لمدة ${p.days} يومًا</p><hr><p>${icon('operations')} ${limits.operations??'لم يحدد'} عمليات جرد</p><p>${icon('team')} ${limits.users??'لم يحدد'} مستخدمين</p><p>${icon('review')} التفعيل بعد المراجعة</p><button onclick="go('plans')">تغيير الباقة</button><small>الحد يشمل إجمالي العمليات المنشأة؛ إغلاق عملية لا يعيد رصيدها.</small></aside>`};
settings=function(){return oldSettings2()+`<section class="panel"><div class="scan"><h2>إدارة منصة RO</h2><p class="muted">واجهة السوبر أدمن وموظفي الإدارة، وحدود الباقات وطلبات العمليات الإضافية ومحاولات الدخول التجريبية.</p><button class="primary" onclick="go('platform')">فتح إدارة النظام ${icon('settings')}</button></div></section>`};
function addonsPage(){return head('كمّل جردك، بمرونة.','كل عملية إضافية تمنحك إنشاء عملية جديدة واحدة. إغلاق العملية لا يعيد الرصيد.','<button onclick="go(\'operations\')">العودة للعمليات</button>')+usageStrip()+`<div class="warning">طلبات شراء تجريبية على هذا الجهاز فقط؛ لا توجد بيانات تحويل معتمدة أو دفع فعلي.</div><div class="addon-grid">${[[1,50],[2,70]].map(([n,price])=>`<article class="pricing"><span class="badge">${n===2?'وفّر 30 ريالًا':'رصيد إضافي'}</span><h2>${n===1?'عملية جرد واحدة':'عمليتا جرد'}</h2><div class="price">${price} <small>ر.س</small></div><p class="muted">${n===2?'35 ريالًا للعملية':'50 ريالًا للعملية'} · تضاف بعد مراجعة الإيصال</p><button class="primary" onclick="requestAddon(${n})">طلب الإضافة ${icon('plans')}</button></article>`).join('')}</div><section class="panel"><div class="panel-title"><h2>طلبات العمليات الإضافية</h2></div><div class="table-wrap"><table><thead><tr><th>الطلب</th><th>العمليات</th><th>المبلغ</th><th>الحالة</th></tr></thead><tbody>${db.addonRequests.map(r=>`<tr><td>${esc(r.id)}</td><td>${r.quantity}</td><td>${r.amount} ر.س</td><td><span class="badge ${r.status==='pending'?'amber':'gray'}">${statusName(r.status)}</span>${r.reason?'<small>'+esc(r.reason)+'</small>':''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">لا توجد طلبات إضافية حتى الآن.</td></tr>'}</tbody></table></div></section>`}
function addonPrice(n){if(n!==1&&n!==2)throw Error('الخيارات المتاحة عملية واحدة أو عمليتان');return n===1?50:70}
function requestAddon(quantity){if(!canManage())return;const amount=addonPrice(quantity);modal(`<h2>شراء ${quantity===1?'عملية إضافية':'عمليتين إضافيتين'}</h2><p>المبلغ: ${amount} ريالًا. الرصيد يضاف بعد المراجعة.</p><div class="warning">أرفق ملف اختبار فقط؛ لا تُجرِ تحويلًا فعليًا.</div><label class="field">إيصال التحويل<input type="file" name="receipt" accept="image/png,image/jpeg,application/pdf" required></label><label class="field">مرجع التحويل<input name="ref" maxlength="100"></label>${modalButtons('إرسال الطلب التجريبي')}`,async f=>{let file=f.get('receipt');await validReceipt(file);let id='ADD-'+newId().slice(0,8);await storeReceipt(id,file);db.addonRequests.unshift({id,quantity,amount,status:'pending',company:'شركة أوركيد · مساحة تجريبية',fileName:file.name,transferRef:f.get('ref').trim(),created:new Date().toISOString()});save('طلب عمليات إضافية '+id);closeDialog();render();toast('الطلب قيد المعالجة — لم يضف رصيد بعد')})}
function approveAddon(id,decision,reason=''){if(!canPlatform('subscriptions'))throw Error('صلاحية مراجعة الاشتراكات مطلوبة');const r=db.addonRequests.find(x=>x.id===id);if(!r||r.status!=='pending')throw Error('تمت معالجة الطلب مسبقًا');if(!['approved','rejected'].includes(decision))throw Error('قرار غير صحيح');if(decision==='rejected'&&!reason.trim())throw Error('اكتب سبب الرفض');if(r.amount!==addonPrice(r.quantity))throw Error('مبلغ الطلب غير مطابق');if(decision==='approved')db.addonCredits+=r.quantity;r.status=decision;r.reason=reason;r.reviewedAt=new Date().toISOString();r.actor=platformRoles[db.platformRole];save('مراجعة طلب العمليات '+id)}
function reviewAddon(id){if(!canPlatform('subscriptions'))return toast('لا تملك صلاحية مراجعة الاشتراكات');let r=db.addonRequests.find(x=>x.id===id);if(!r)return;modal(`<h2>طلب ${esc(id)}</h2><p>${r.quantity} عمليات · ${r.amount} ر.س · ${esc(r.company)}</p><p>مرجع التحويل: ${esc(r.transferRef)||'—'}</p><button type="button" onclick="downloadReceipt('${id}')">تنزيل الإيصال</button><label class="field">القرار<select name="decision"><option value="approved">قبول وإضافة الرصيد التجريبي</option><option value="rejected">رفض</option></select></label><label class="field">سبب القرار<textarea name="reason" maxlength="500"></textarea></label>${modalButtons('حفظ القرار')}`,f=>{approveAddon(id,f.get('decision'),f.get('reason').trim());closeDialog();render();toast('تمت معالجة الطلب مرة واحدة')})}
function platformPage(){initPlatform();const tabs=[['overview','نظرة عامة'],...(canPlatform('subscriptions')?[['subscriptions','طلبات الاشتراك'],['addons','العمليات الإضافية']]:[]),...(canPlatform('security')?[['security','محاولات الدخول']]:[]),...(db.platformRole==='superadmin'?[['limits','حدود الباقات'],['staff','موظفو الإدارة']]:[])];if(!tabs.some(([k])=>k===platformTab))platformTab='overview';return `<div class="platform-heading">${head('إدارة منصة RO','مساحة مستقلة للسوبر أدمن وموظفي إدارة النظام.','<button onclick="go(\'settings\')">مساحة الشركة</button>')}<div class="warning">إدارة تجريبية على هذا المتصفح. الأدوار والتنبيهات هنا للمعاينة، ولا تمثل حماية دخول أو مراقبة أجهزة فعلية.</div><label class="platform-role">معاينة دور الإدارة<select onchange="db.platformRole=this.value;save();render()">${Object.entries(platformRoles).map(([k,v])=>`<option value="${k}" ${db.platformRole===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="platform-tabs">${tabs.map(([k,t])=>`<button class="${platformTab===k?'active':''}" onclick="platformTab='${k}';render()">${icon(k==='security'?'review':k==='staff'?'team':k==='limits'?'settings':'plans')}${t}${k==='security'&&db.securityEvents.some(x=>!x.reviewed)?'<b>'+db.securityEvents.filter(x=>!x.reviewed).length+'</b>':''}</button>`).join('')}</div>${({overview:platformOverview,subscriptions:()=>adminPage(),addons:platformAddons,security:platformSecurity,limits:platformLimits,staff:platformStaffPage})[platformTab]()}`}
function platformOverview(){return `<div class="stats">${[['security','محاولات من أجهزة أخرى',db.securityEvents.filter(x=>!x.reviewed).length],['subscriptions','طلبات اشتراك معلقة',db.requests.filter(x=>x.status==='pending').length],['addons','طلبات عمليات إضافية',db.addonRequests.filter(x=>x.status==='pending').length],['staff','موظفو الإدارة',db.platformStaff.length]].filter(([tab])=>db.platformRole==='superadmin'||(tab==='security'?canPlatform('security'):tab==='subscriptions'||tab==='addons'?canPlatform('subscriptions'):false)).map(([tab,title,n])=>`<div class="stat"><div class="stat-top">${title}${icon('review')}</div><strong>${n}</strong><button class="link" onclick="platformTab='${tab}';render()">عرض ${icon('arrow')}</button></div>`).join('')}</div><section class="panel"><div class="scan"><h2>صلاحيات موظفي الإدارة</h2><p class="muted">السوبر أدمن يدير الباقات والموظفين وكل الطلبات. موظف الاشتراكات يراجع الإيصالات والرصيد الإضافي. موظف مراقبة الدخول يتابع محاولات الأجهزة ويسجل المراجعة.</p></div></section>`}
function platformLimits(){if(db.platformRole!=='superadmin')return '';return `<div class="warning">الباقة الأولى: عمليتا جرد كما حددت. بقية حدود العمليات وحدود المستخدمين لم تحدد بعد؛ تُضبط هنا قبل استخدامها.</div><div class="limit-grid">${packages.map((p,i)=>`<form class="panel limit-card" onsubmit="saveLimits(event,${i})"><h2>${p.name}</h2><label class="field">إجمالي عمليات الجرد<input type="number" name="operations" min="1" max="1000000" step="1" required value="${db.planLimits[i].operations??''}" placeholder="لم يحدد"></label><label class="field">عدد المستخدمين شامل حساب الشركة<input type="number" name="users" min="1" max="1000000" step="1" required value="${db.planLimits[i].users??''}" placeholder="لم يحدد"></label><button class="primary wide">حفظ حدود الباقة</button></form>`).join('')}</div><div class="panel"><div class="scan"><h3>الباقة المعاينة لمساحة الشركة</h3><select aria-label="باقة مساحة الشركة" onchange="db.plan=Number(this.value);save();render()">${packages.map((p,i)=>`<option value="${i}" ${db.plan===i?'selected':''}>${p.name}</option>`).join('')}</select><p class="muted">تغيير المعاينة لا يفعّل اشتراكًا فعليًا ولا يصفر عدد العمليات السابقة.</p>${usageStrip()}</div></div>`}
function validateLimits(operations,users){if(!Number.isSafeInteger(operations)||operations<1||operations>1e6||!Number.isSafeInteger(users)||users<1||users>1e6)throw Error('أدخل أعدادًا صحيحة من 1 إلى مليون');return {operations,users}}
function saveLimits(event,i){event.preventDefault();if(db.platformRole!=='superadmin')return;try{const f=new FormData(event.target);db.planLimits[i]=validateLimits(Number(f.get('operations')),Number(f.get('users')));save('تعديل حدود باقة '+packages[i].name);render();toast('تم حفظ الحدود التجريبية')}catch(err){toast(err.message)}}
function platformAddons(){if(!canPlatform('subscriptions'))return '';return `<section class="panel"><div class="panel-title"><h2>طلبات شراء عمليات الجرد</h2><small>عملية 50 ريالًا · عمليتان 70 ريالًا</small></div><div class="table-wrap"><table><thead><tr><th>الشركة</th><th>العمليات / المبلغ</th><th>الحالة</th><th>المراجعة</th></tr></thead><tbody>${db.addonRequests.map(r=>`<tr><td>${esc(r.company)}<small>${esc(r.id)}</small></td><td>${r.quantity} عمليات<small>${r.amount} ر.س</small></td><td>${statusName(r.status)}</td><td>${r.status==='pending'?`<button onclick="reviewAddon('${r.id}')">مراجعة الإيصال</button>`:'<span class="badge gray">تمت المعالجة</span>'}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">لا توجد طلبات</td></tr>'}</tbody></table></div></section>`}
function platformSecurity(){if(!canPlatform('security'))return '';return `<div class="security-note"><p>عند ربط الخادم: يظهر هنا دخول حساب شركة أو موظف من جهاز غير معتمد، مع الحساب والوقت والجهاز ونتيجة المحاولة.</p><button onclick="simulateDeviceEvent()">${icon('review')} محاكاة محاولة من جهاز آخر</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>الحساب</th><th>الجهاز</th><th>الوقت</th><th>الحالة</th><th>المراجعة</th></tr></thead><tbody>${db.securityEvents.map(e=>`<tr><td>${esc(e.name)}<small>${e.kind==='company'?'حساب شركة':'موظف جرد'} · ${esc(e.company)}</small></td><td>${esc(e.device)}<small>جهاز آخر — حدث محاكاة</small></td><td>${new Date(e.created).toLocaleString('ar-SA')}</td><td><span class="badge ${e.reviewed?'gray':'amber'}">${e.reviewed?'تمت المراجعة':'محاولة محاكية غير معتمدة'}</span></td><td>${e.reviewed?esc(e.reviewedBy):`<button onclick="reviewDeviceEvent('${e.id}')">تسجيل المراجعة</button>`}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">لا توجد أحداث. المراقبة الفعلية تنتظر ربط الخادم.</td></tr>'}</tbody></table></div></section>`}
function simulateDeviceEvent(){if(!canPlatform('security'))return;modal(`<h2>محاكاة دخول من جهاز آخر</h2><p>ينشئ تنبيه اختبار فقط؛ لا ينفذ محاولة دخول فعلية.</p><label class="field">الحساب<select name="kind"><option value="company">حساب الشركة</option><option value="employee">موظف جرد</option></select></label><label class="field">وصف الجهاز<input name="device" required maxlength="100" value="جوال جديد — جهاز تجريبي"></label>${modalButtons('إضافة حدث محاكاة')}`,f=>{db.securityEvents.unshift({id:newId(),kind:f.get('kind'),name:f.get('kind')==='company'?'حساب الشركة':user('u2'),company:'شركة أوركيد · تجربة',device:f.get('device').trim(),created:new Date().toISOString(),reviewed:false});save('محاكاة محاولة جهاز آخر');closeDialog();render()})}
function reviewDeviceEvent(id){if(!canPlatform('security'))return;let e=db.securityEvents.find(x=>x.id===id);if(!e||e.reviewed)return;e.reviewed=true;e.reviewedBy=platformRoles[db.platformRole];e.reviewedAt=new Date().toISOString();save('مراجعة تنبيه جهاز '+id);render()}
function platformStaffPage(){if(db.platformRole!=='superadmin')return '';return `<section class="panel"><div class="panel-title"><h2>موظفو إدارة النظام</h2><button onclick="addPlatformStaff()">إضافة موظف إدارة ${icon('team')}</button></div><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>البريد</th><th>الصلاحية</th><th>الحالة</th></tr></thead><tbody>${db.platformStaff.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${platformRoles[u.role]}</td><td><span class="badge gray">معاينة — دون حساب دخول فعلي</span></td></tr>`).join('')||'<tr><td colspan="4" class="empty">لم تضف موظفي إدارة بعد</td></tr>'}</tbody></table></div></section>`}
function addPlatformStaff(){if(db.platformRole!=='superadmin')return;modal(`<h2>إضافة موظف إدارة</h2><p>للمعاينة فقط، لا تُرسل دعوة ولا يُنشأ حساب دخول.</p><label class="field">الاسم<input name="name" required maxlength="100"></label><label class="field">البريد الإلكتروني<input name="email" type="email" required maxlength="160"></label><label class="field">الصلاحية<select name="role"><option value="subscriptions">موظف الاشتراكات</option><option value="security">موظف مراقبة الدخول</option></select></label>${modalButtons('إضافة الموظف التجريبي')}`,f=>{let email=f.get('email').trim().toLowerCase(),name=f.get('name').trim();if(!name)throw Error('أدخل الاسم');if(db.platformStaff.some(u=>u.email===email))throw Error('البريد مضاف مسبقًا');db.platformStaff.push({id:newId(),name,email,role:f.get('role')});save('إضافة موظف إدارة تجريبي');closeDialog();render()})}
const baseReviewRequest=reviewRequest,baseAdminPage=adminPage;reviewRequest=function(id){if(!canPlatform('subscriptions'))return toast('صلاحية مراجعة الاشتراكات مطلوبة');return baseReviewRequest(id)};adminPage=function(){if(!canPlatform('subscriptions'))return '<div class="panel empty">هذا الدور لا يملك صلاحية مراجعة الاشتراكات.</div>';return baseAdminPage()};
// Keep video mounted and camera running when a count is saved.
attachScan=function(){const form=$('#scanForm');if(!form)return;form.elements.operation.onchange=e=>{selected=e.target.value;render()};form.elements.barcode.oninput=()=>{scanLocked=!!form.elements.barcode.value.trim()};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),o=op(f.get('operation')),barcode=f.get('barcode').trim(),qty=Number(f.get('qty')),uid=db.role==='employee'?activeUser():f.get('employee'),location=f.get('location').trim();if(!o||o.status!=='open'||!visibleOps().some(x=>x.id===o.id)||!o.staff.includes(uid)||!barcode||!location||!Number.isSafeInteger(qty)||qty<0||qty>1e9)return toast('تحقق من العملية والموظف والباركود والكمية والموقع');db.logs.push({id:newId(),op:o.id,barcode,qty,user:uid,location,note:f.get('note').trim(),time:new Date().toISOString(),excluded:false});delete db.resolutions[[o.id,barcode,location].join('|')];save('تسجيل جرد بواسطة '+user(uid));form.elements.barcode.value='';form.elements.qty.value=1;form.elements.note.value='';scanLocked=false;lastBarcodeAt=Date.now();$('#cameraStatus').textContent=cameraStream?'تم حفظ '+barcode+' — الماسح مستمر، وجّه الصنف التالي.':'تم حفظ '+barcode+' — جاهز للصنف التالي.';toast('تم حفظ '+qty+' وحدات. جاهز للصنف التالي.')}};
const priorRender=render;render=function(){initPlatform();priorRender();if(canManage()&&!document.body.classList.contains('public-flow')){const nav=$('#nav');nav.insertAdjacentHTML('beforeend',`<button class="${page==='platform'?'active':''}" onclick="go('platform')"><span>${icon('settings')}</span><em style="font-style:normal">إدارة المنصة</em></button>`)}if(page==='platform'){$('#breadcrumb').textContent='إدارة منصة RO';$('#app').classList.add('platform-view')}else $('#app').classList.remove('platform-view')};
render();
